"use client";

import { useEffect, useState } from "react";
import { usePathname } from "next/navigation";

export function AdminCommunityBadge({ className = "" }: { className?: string }) {
  const [count, setCount] = useState(0);
  const pathname = usePathname();

  useEffect(() => {
    let cancelled = false;

    async function load() {
      try {
        const res = await fetch("/api/admin/moderation/count", { cache: "no-store" });
        if (!res.ok) return;
        const data = await res.json();
        if (!cancelled) setCount(Number(data?.count) || 0);
      } catch {
        // ignore transient fetch errors, keep last known count
      }
    }

    void load();
    const timer = setInterval(load, 30000);
    return () => {
      cancelled = true;
      clearInterval(timer);
    };
  }, []);

  if (pathname.startsWith("/admin/moderation")) return null;
  if (!count) return null;

  return (
    <span
      aria-label={`${count} pending items`}
      title={`${count} pending items`}
      className={`inline-flex items-center justify-center min-w-[18px] h-[18px] rounded-full bg-red-500 text-white text-[10px] font-bold leading-none px-1 ${className}`}
    >
      {count > 10 ? "10+" : count}
    </span>
  );
}